"""Freeze reviewed text and generate finite first-push Actions. No network/provider calls."""
from pathlib import Path
import hashlib,json
HERE=Path(__file__).resolve().parent
sha=lambda p:hashlib.sha256(Path(p).read_bytes()).hexdigest()
read=lambda p:json.loads(Path(p).read_text('utf8'))
def write(name,value):
    data=(json.dumps(value,ensure_ascii=False,indent=2)+'\n') if not isinstance(value,str) else value
    (HERE/name).write_bytes(data.encode())
req=read(HERE/'request.json');assert len(req['units'])==64 and req['model']=='gemini-3.8-flash-tts' and req['automaticRetries']==0
package=req['deploymentTarget']['packagePath'];branch=req['deploymentTarget']['branch']
files=['worker.py','request.json','runtime.json','source-audit.json','source-coverage.json','independent-source-review.json','scientific-contract.json','content-identities.json','reuse-inventory.json','PUBLIC-PROJECTION-PATTERN.en.md','worker-derivation.json','implementation-dependency-pins.json','README.en.md','offline_tests.py','freeze_package.py','batch_status.py','playback_gate.py','trigger-policy.json','.gitignore','vendor/pipeline-engine.py','vendor/course/manifest.json']
files += ['narration-'+loc+'.json' for loc in ['en','ar-EG','it','de']]+['inputs/source-'+loc+'.json' for loc in ['en','ar-EG','it','de']]
freeze={'schemaVersion':2,'stepId':'S2-15','sha256':{n:sha(HERE/n) for n in files},'maximumTTSCalls':64,'maximumBlindAudioReviewCalls':64,'maximumASRInvocations':64,'maximumMetadataGETs':2,'maximumPerPartPerKind':1,'automaticRetries':0,'all64PartsRequired':True}
write('freeze.json',freeze)
rq,wr,fr=sha(HERE/'request.json'),sha(HERE/'worker.py'),sha(HERE/'freeze.json')
lines=['name: S2-15 four-locale narration r1 first push only','on:','  push:','    branches:','      - '+branch,'permissions:','  contents: read','concurrency:','  group: s215-connected-r1-'+rq,'  cancel-in-progress: false','env:','  PACKAGE: '+package,'  REQUEST_SHA: '+rq,'  WORKER_SHA: '+wr,'  FREEZE_SHA: '+fr,"  PYTHONUNBUFFERED: '1'","  HF_HUB_DISABLE_TELEMETRY: '1'","  OMP_NUM_THREADS: '2'",'jobs:','  narration:','    if: >-',"      github.run_attempt == 1 && github.event_name == 'push' &&","      github.repository == 'cabicci/viva-ai-systems-55d35820' && github.event.repository.id == 1272666418 &&","      github.event.repository.private == false && github.event.repository.fork == false &&","      github.ref == 'refs/heads/"+branch+"' && github.ref_type == 'branch' &&","      github.event.ref == github.ref && github.event.created == true &&","      github.event.deleted == false && github.event.forced == false &&","      github.event.before == '0000000000000000000000000000000000000000' && github.event.after == github.sha",'    runs-on: ubuntu-22.04','    timeout-minutes: 360','    steps:','      - uses: actions/checkout@11d5960a326750d5838078e36cf38b85af677262','      - uses: actions/setup-python@a26af69be951a213d495a4c3e4e4022e16d87065','        with:',"          python-version: '3.11'",'      - name: Offline validate frozen complete source-bound request','        run: |','          cd "$PACKAGE"','          python worker.py validate','      - name: Exact model metadata preflight no fallback','        id: preflight','        env:','          GEMINI_API_KEY: ${{ secrets.GEMINI_API_KEY }}','        run: |','          cd "$PACKAGE"','          python worker.py preflight']
# All audio attempts/transfers finish before independent diagnostics begin.
for i,u in enumerate(req['units']):
    uid=u['id'];n=f'{i+1:03d}'
    lines += ['      - name: One TTS attempt '+uid,'        id: tts'+n,'        if: ${{ !cancelled() && steps.preflight.outcome == \'success\' }}','        continue-on-error: true','        timeout-minutes: 20','        env:','          GEMINI_API_KEY: ${{ secrets.GEMINI_API_KEY }}','        run: |','          cd "$PACKAGE"','          python worker.py produce --unit '+uid,'      - name: Immediate finished audio upload '+uid,'        id: upload'+n,'        if: ${{ !cancelled() && steps.tts'+n+'.outcome == \'success\' }}','        uses: actions/upload-artifact@ea165f8d65b6e75b540449e92b4886f43607fa02','        with:','          name: s215-connected-r1-'+uid+'-audio','          path: ${{ env.PACKAGE }}/output/'+uid+'/','          if-no-files-found: error','          retention-days: 30','      - name: Bind exact audio transfer '+uid,'        id: bind'+n,'        if: ${{ !cancelled() && steps.upload'+n+'.outcome == \'success\' }}','        continue-on-error: true','        env:','          AUDIO_ARTIFACT_ID: ${{ steps.upload'+n+'.outputs.artifact-id }}','          AUDIO_ARTIFACT_DIGEST: ${{ steps.upload'+n+'.outputs.artifact-digest }}','        run: |','          cd "$PACKAGE"','          python worker.py uploaded --unit '+uid+' --artifact-id "$AUDIO_ARTIFACT_ID" --artifact-digest "$AUDIO_ARTIFACT_DIGEST"']
lines += ['      - name: Install hash verified independent ASR runtime after all audio transfers','        id: asrsetup','        if: ${{ !cancelled() && steps.preflight.outcome == \'success\' }}','        run: |','          cd "$PACKAGE"','          python -m pip download --no-deps --dest wheels faster-whisper==1.2.1','          python worker.py verify-wheel','          python -m pip install --disable-pip-version-check --report output/pip-install-report.json wheels/faster_whisper-1.2.1-*.whl']
for i,u in enumerate(req['units']):
    uid=u['id'];n=f'{i+1:03d}'
    lines += ['      - name: One blind review and independent ASR '+uid,'        if: ${{ !cancelled() && steps.bind'+n+'.outcome == \'success\' }}','        continue-on-error: true','        timeout-minutes: 25','        env:','          GEMINI_API_KEY: ${{ secrets.GEMINI_API_KEY }}','        run: |','          cd "$PACKAGE"','          python worker.py blind-review --unit '+uid+' || true','          python worker.py asr --unit '+uid+' || true','          python worker.py compare --unit '+uid,'      - name: Preserve immediate part diagnostic evidence '+uid,'        if: always()','        uses: actions/upload-artifact@ea165f8d65b6e75b540449e92b4886f43607fa02','        with:','          name: s215-connected-r1-'+uid+'-review','          path: ${{ env.PACKAGE }}/output/'+uid+'/','          if-no-files-found: warn','          retention-days: 30']
lines += ['      - name: Report all64 required candidate recordings and missing diagnostics','        if: always()','        run: |','          cd "$PACKAGE"','          python batch_status.py','      - name: Preserve all finished audio partial attempts and frozen provenance','        if: always()','        uses: actions/upload-artifact@ea165f8d65b6e75b540449e92b4886f43607fa02','        with:','          name: s215-connected-r1-complete-evidence','          if-no-files-found: warn','          retention-days: 30','          path: |','            ${{ env.PACKAGE }}/output/','            ${{ env.PACKAGE }}/request.json','            ${{ env.PACKAGE }}/runtime.json','            ${{ env.PACKAGE }}/freeze.json','            ${{ env.PACKAGE }}/worker.py','            ${{ env.PACKAGE }}/source-audit.json','            ${{ env.PACKAGE }}/offline-verification.json']
workflow='s2-15-narration-r1.yml';write(workflow,'\n'.join(lines)+'\n')
allow=[{'source':n,'destination':package+'/'+n,'sha256':sha(HERE/n)} for n in files+['freeze.json','offline-verification.json'] if (HERE/n).exists()]
allow.append({'source':workflow,'destination':'.github/workflows/'+workflow,'sha256':sha(HERE/workflow)})
write('publication-allowlist.json',{'repository':req['deploymentTarget']['repository'],'branch':branch,'noMainEdits':True,'onlyTheseFiles':allow,'excludes':['parent private sources','received audio','local QA media','offline-fixtures','__pycache__','output','credentials/environment files']})
receipt={'status':'FROZEN_TEXT_PACKAGE_NOT_LAUNCHED','requestSHA256':rq,'workerSHA256':wr,'freezeSHA256':fr,'workflowSHA256':sha(HERE/workflow),'requiredUnits':64,'frozenFiles':len(files),'all64AudioUploadsBeforeAnyDiagnostics':True,'firstPushOnly':True,'publicationPerformed':False,'providerCalls':0,'actualAudioAcceptance':False,'offlineVerificationRequired':True}
write('package-receipt.json',receipt)
print(json.dumps(receipt,indent=2))
